using System;using System.IO;namespace EarlyPlaytest {public static class EpSession {public static readonly string Output=Load();static string Load(){string path=Path.Combine(Path.GetDirectoryName(typeof(EpSession).Assembly.Location),"ep4_session.txt");if(!File.Exists(path))throw new InvalidOperationException("[EP4] No active session. Run the extracted Start-Earlyplaytest.ps1 to create session markers.");string output=File.ReadAllText(path).Trim();if(!Path.IsPathRooted(output)||!Directory.Exists(output))throw new InvalidOperationException("[EP4] Invalid session output: "+output);return output;}}}
